{"expected_revision_id": "c3438716-9f2a-45ca-bd23-cd794fc6f7ac", "source": "module TopModule (
    input  c,
    input  d,
    output [3:0] mux_in
);
    // Values of the Karnaugh map for each column ab (selects the 4-to-1 mux):
    //   ab = 00 -> mux_in[0]
    //   ab = 01 -> mux_in[1]
    //   ab = 11 -> mux_in[2]
    //   ab = 10 -> mux_in[3]
    assign mux_in[0] = c | d;    // cd: 00->0, 01->1, 11->1, 10->1
    assign mux_in[1] = 1'b0;     // cd: 00->0, 01->0, 11->0, 10->0
    assign mux_in[2] = c & d;    // cd: 00->0, 01->0, 11->1, 10->0
    assign mux_in[3] = c | ~d;   // cd: 00->1, 01->0, 11->1, 10->1
endmodule
"}
